#!/usr/bin/env bash
# YoureCom Standard: clones the required YoureCom packages of package.xml (and those of .github/phpstan-packages.txt) next to the plugin (CI only), so PHPStan
# finds their classes like in the local plugins folder. Managed by _dev/standard (apply.php), do not edit here.
#
# Usage: TOKEN=<token> bash .github/scripts/checkout-dependencies.sh <plugin dir>
set -euo pipefail

PLUGIN="${1:-.}"
printf "parameters:
  scanDirectories: []
" > "$PLUGIN/phpstan.ci.packages.neon"
BRANCH="${DEPENDENCY_BRANCH:-6.2}"
mapfile -t PACKAGES < <(sed -n 's:.*<requiredpackage[^>]*>\(de\.yourecom\.[^<]*\)</requiredpackage>.*:\1:p' "$PLUGIN/package.xml")

# packages the plugin only uses when they are installed (no requiredpackage): one per line in .github/phpstan-packages.txt
if [[ -f "$PLUGIN/.github/phpstan-packages.txt" ]]; then
  mapfile -t -O "${#PACKAGES[@]}" PACKAGES < <(sed -n 's:^\(de\.yourecom\.[A-Za-z0-9.]*\)[[:space:]]*$:\1:p' "$PLUGIN/.github/phpstan-packages.txt")
fi

DONE=" "
WOLTLAB=" "
finish() {
  # public WoltLab packages the plugin uses without requiring them in the CI (conversation, ...): one name per line in
  # .github/phpstan-woltlab.txt, cloned from github.com/WoltLab, their lib folders are scanned like the YoureCom ones
  if [[ -f "$PLUGIN/.github/phpstan-woltlab.txt" ]]; then
    while read -r W; do
      [[ "$W" =~ ^com\.woltlab\.[A-Za-z0-9.]+$ ]] || continue
      if git clone --quiet --depth 1 --branch "$BRANCH" "https://github.com/WoltLab/${W}.git" "$W"; then
        WOLTLAB+="$W "
      else
        echo "::warning::$W could not be cloned, PHPStan runs without it"
      fi
    done < "$PLUGIN/.github/phpstan-woltlab.txt"
  fi
  
  # PHPStan has to scan every cloned package, not only the ones its own phpstan.ci.neon lists: phpstan.ci.packages.neon is
  # included by phpstan.ci.neon (optional include), generated here from what was actually cloned
  {
    echo "# generated by .github/scripts/checkout-dependencies.sh (CI only), do not edit"
    echo "parameters:"
    echo "  bootstrapFiles:"
    echo "    - '../wcf/constants.php'"
    for P in $DONE; do
      [[ -f "$P/constants.php" ]] && echo "    - '../$P/constants.php'"
    done
    # the constants of the packages hold dummy values (define('X', 0)): without this PHPStan takes them as fixed and reports
    # every check of an option as always true or false
    echo "  dynamicConstantNames:"
    echo "    - TIME_NOW"
    for P in $DONE; do
      [[ -f "$P/constants.php" ]] && sed -n "s/^[^\/#*]*define('\([A-Za-z0-9_]*\)'.*/    - \1/p" "$P/constants.php"
    done
    echo "  scanDirectories:"
    for P in $DONE; do
      for D in files/lib files_wcf/lib; do
        [[ -d "$P/$D" ]] && echo "    - ../$P/$D/"
      done
    done
    for P in $WOLTLAB; do
      [[ -d "$P/files/lib" ]] && echo "    - ../$P/files/lib/"
    done
    :
  } > "$PLUGIN/phpstan.ci.packages.neon"
  
}
trap finish EXIT

if [[ ${#PACKAGES[@]} -eq 0 ]]; then
  echo "No required YoureCom packages."
  exit 0
fi

if [[ -z "${TOKEN:-}" ]]; then
  echo "::warning::YOURECOM_DEPENDENCY_TOKEN is not set, PHPStan runs without: ${PACKAGES[*]}"
  exit 0
fi

# the packages those packages require, too (clan.board.wbb -> clan.board -> clan): PHPStan needs their classes as well
QUEUE=("${PACKAGES[@]}")
for ((i = 0; i < ${#QUEUE[@]}; i++)); do
  PACKAGE="${QUEUE[$i]}"
  [[ "$DONE" == *" $PACKAGE "* ]] && continue
  DONE+="$PACKAGE "
  # the repositories keep the camel case of the plugin folders, GitHub resolves the name case-insensitively
  git clone --quiet --depth 1 --branch "$BRANCH" "https://x-access-token:${TOKEN}@github.com/YoureCom/${PACKAGE}.git" "$PACKAGE" \
    || git clone --quiet --depth 1 "https://x-access-token:${TOKEN}@github.com/YoureCom/${PACKAGE}.git" "$PACKAGE" \
    || git clone --quiet --depth 1 --branch "$BRANCH" "https://x-access-token:${TOKEN}@github.com/YoureCom/${PACKAGE%%[0-9]}.git" "$PACKAGE" \
    || { echo "::warning::$PACKAGE could not be cloned, PHPStan runs without it"; continue; }
  echo "Cloned $PACKAGE"
  mapfile -t NESTED < <(sed -n 's:.*<requiredpackage[^>]*>\(de\.yourecom\.[^<]*\)</requiredpackage>.*:\1:p' "$PACKAGE/package.xml" 2>/dev/null)
  QUEUE+=("${NESTED[@]}")
done
